import itertools
import json

# Decode each ReLU neuron as a Boolean gate over its incoming channels.
# Expressions are built from the weights; only the resulting Boolean expressions
# are evaluated on the 1024 input tuples.
def node(op, **kwargs):
    return {"op": op, **kwargs}

def neg(a):
    return node("not", arg=a)

def combine(op, a, b):
    return node(op, left=a, right=b)

def gate_from_table(variables, values):
    """Build an expression for a Boolean truth table, with variables as ASTs."""
    terms = []
    n = len(variables)
    for bits, result in zip(itertools.product((0, 1), repeat=n), values):
        if result:
            literals = [v if bit else neg(v) for v, bit in zip(variables, bits)]
            if not literals:
                return node("input", index=0)  # replaced by constant handling below
            term = literals[0]
            for literal in literals[1:]:
                term = combine("and", term, literal)
            terms.append(term)
    if not terms:
        return None
    result = terms[0]
    for term in terms[1:]:
        result = combine("or", result, term)
    return result

def eval_expr(expr, x):
    if expr is None:
        return False
    op = expr["op"]
    if op == "input":
        return bool(x[expr["index"]])
    if op == "not":
        return not eval_expr(expr["arg"], x)
    a = eval_expr(expr["left"], x)
    b = eval_expr(expr["right"], x)
    return {"and": a and b, "or": a or b, "xor": a != b,
            "nand": not (a and b), "nor": not (a or b)}[op]

def make_gate(variables, table):
    if not any(table):
        return None
    if all(table):
        return {"op": "not", "arg": {"op": "input", "index": 0,
                                      "_constant_true": True}}
    # Build an OR of minterms; constants are represented internally as
    # constant nodes and handled by eval_expr.
    terms = []
    for bits, result in zip(itertools.product((0, 1), repeat=len(variables)), table):
        if result:
            literals = [v if bit else neg(v) for v, bit in zip(variables, bits)]
            if not literals:
                return {"op": "const", "value": 1}
            term = literals[0]
            for literal in literals[1:]:
                term = combine("and", term, literal)
            terms.append(term)
    result = terms[0]
    for term in terms[1:]:
        result = combine("or", result, term)
    return result

def eval_expr(expr, x):
    if expr is None:
        return False
    op = expr["op"]
    if op == "const":
        return bool(expr["value"])
    if op == "input":
        return bool(x[expr["index"]])
    if op == "not":
        return not eval_expr(expr["arg"], x)
    a = eval_expr(expr["left"], x)
    b = eval_expr(expr["right"], x)
    return {"and": a and b, "or": a or b, "xor": a != b,
            "nand": not (a and b), "nor": not (a or b)}[op]

def decode_layer(W, b, previous):
    result = []
    for row in range(W.shape[0]):
        active = [i for i in range(W.shape[1]) if W[row, i] != 0]
        variables = [previous[i] for i in active]
        table = []
        for bits in itertools.product((0, 1), repeat=len(active)):
            z = float(b[row]) + sum(float(W[row, i]) * bit
                                     for i, bit in zip(active, bits))
            y = max(0.0, z)
            if y not in (0.0, 1.0):
                raise ValueError(f"Neuron {row} is not binary: {y}")
            table.append(int(y))
        result.append(make_gate(variables, table))
    return result

def readout_class(W, b, final_channels):
    active = [i for i in range(W.shape[1]) if any(W[:, i] != 0)]
    variables = [final_channels[i] for i in active]
    table = []
    for bits in itertools.product((0, 1), repeat=len(active)):
        logits = [float(b[k]) + sum(float(W[k, i]) * bit
                                    for i, bit in zip(active, bits))
                  for k in range(W.shape[0])]
        table.append(int(max(range(len(logits)), key=lambda k: logits[k]) == 1))
    return make_gate(variables, table)

