import itertools
import json
import numpy as np

def make_input(i):
    return {"kind": "input", "index": i}

def make_lut(args, rows):
    # rows maps tuples of incoming channel values to this neuron's output.
    return {"kind": "lut", "args": args, "rows": rows}

def decode_layer(W, b, previous, domains):
    current, current_domains = [], []
    for r in range(W.shape[0]):
        active = [i for i in range(W.shape[1]) if W[r, i] != 0]
        args = [previous[i] for i in active]
        arg_domains = [domains[i] for i in active]
        rows, outputs = {}, set()

        for values in itertools.product(*arg_domains):
            z = float(b[r]) + sum(
                float(W[r, i]) * value for i, value in zip(active, values)
            )
            y = max(0.0, z)
            rows[tuple(values)] = y
            outputs.add(y)

        current.append(make_lut(args, rows))
        current_domains.append(sorted(outputs))
    return current, current_domains

def decode_readout(W, b, final, domains):
    active = [i for i in range(W.shape[1]) if np.any(W[:, i] != 0)]
    args = [final[i] for i in active]
    arg_domains = [domains[i] for i in active]
    rows = {}

    for values in itertools.product(*arg_domains):
        logits = [
            float(b[k]) + sum(
                float(W[k, i]) * value for i, value in zip(active, values)
            )
            for k in range(W.shape[0])
        ]
        rows[tuple(values)] = int(max(range(len(logits)), key=logits.__getitem__) == 1)

    return make_lut(args, rows)

def evaluate(expr, x, cache):
    key = id(expr)
    if key in cache:
        return cache[key]
    if expr["kind"] == "input":
        value = int(x[expr["index"]])
    else:
        args = tuple(evaluate(arg, x, cache) for arg in expr["args"])
        value = expr["rows"][args]
    cache[key] = value
    return value

h = [make_input(i) for i in range(10)]
domains = [[0, 1] for _ in range(10)]

for layer in range(4):
    h, domains = decode_layer(
        np.asarray(W[f"target.w{layer}"]),
        np.asarray(W[f"target.b{layer}"]),
        h,
        domains,
    )

target = decode_readout(
    np.asarray(W["target.out"]),
    np.asarray(W["target.bias"]),
    h,
    domains,
)

outputs = [
    int(evaluate(target, bits, {}))
    for bits in itertools.product((0, 1), repeat=10)
]
sub = {"outputs": outputs}
check_submission(sub)
with open("/work/submission.json", "w") as f:
    json.dump(sub, f)
